TEST(MultithreadViewTests, CanAddRemoveBuckets) {
  auto pv = make_balanced_view(5, 10);
  ASSERT_EQ(5, pv->num_buckets());

  std::thread t1([&pv]() {
    auto new_bucket = std::make_shared<Bucket>("new-host.example.com",
                                               std::vector<float>{0.3, 0.6, 0.9});
    ASSERT_EQ(5, pv->num_buckets());
    pv->Add(new_bucket);
  });

